	margin: 1em;
}
/* :checked */
.exq_tab input:checked ~ .exq_tab-content {
	max-height: 250px;
}
/* Icon */
.exq_tab label::after {
	position: absolute;
	right: 0;
	top: 0px;
	display: block;
	width: 3em;
	height: 3em;
	line-height: 3;
	text-align: center;
	-webkit-transition: all .35s;
	-o-transition: all .35s;
	transition: all .35s;
	font-size: 20px;
	color: #bfbfbf;
}
.exq_tab input[type=checkbox] + label::after {
	content: "+";
}
.exq_tab input[type=radio] + label::after {
	content: "\25BC";
}
.exq_tab input[type=checkbox]:checked + label::after {
	transform: rotate(315deg);
}
.exq_tab input[type=radio]:checked + label::after {
	transform: rotateX(180deg);
}
