.selfcheck-radio li input[type="radio"]:checked,
.selfcheck-radio li input[type="radio"]:not(:checked) {
    position: absolute;
    left: -9999px;
}
.selfcheck-radio li input[type="radio"]:checked + label,
.selfcheck-radio li input[type="radio"]:not(:checked) + label
{
    position: relative;
    padding-left: 28px;
    cursor: pointer;
    line-height: 20px;
    display: inline-block;
    color: #666;
}
.selfcheck-radio li input[type="radio"]:checked + label:before,
.selfcheck-radio li input[type="radio"]:not(:checked) + label:before {
	content: '';
    position: absolute;
    left: 0;
    top: 0;
    width: 29px;
    height: 29px;
    background: transparent;
}
.selfcheck-radio li input[type="radio"]:checked + label:after,
.selfcheck-radio li input[type="radio"]:not(:checked) + label:after {
    /* content: '';
    width: 12px;
    height: 12px;
    background: #F87DA9;
    position: absolute;
    top: 4px;
    left: 4px;
    border-radius: 100%;
    -webkit-transition: all 0.2s ease;
    transition: all 0.2s ease; */
}
.selfcheck-radio li input[type="radio"]:not(:checked) + label:after {
    opacity: 0;
    -webkit-transform: scale(0);
    transform: scale(0);
}
.selfcheck-radio li input[type="radio"]:checked + label:after {
    opacity: 1;
    -webkit-transform: scale(1);
    transform: scale(1);
}

