	background: #42d1e1;
}

.arrow i {
    font-size: 60px;
    color: #fff;
    height: 70px;
    display: inline-block;
    width: 65px;
    align-self: center;
}

.std-self .arrow.up {
    left: -45px;
}

.std-self .arrow.down {
	left: -45px;
    top: -60px;
	transform: rotate(180deg);
}

.std-self .arrow.up i {
    align-self: flex-end;
    position: relative;
    top: -15px;
}

.std-self .arrow.down i {
	align-self: flex-end;
    position: relative;
    top: -15px;
    transform: rotate(180deg);
    left: -3px;
}

.std-self .arrow.up .up-arrow {
    border-bottom: 110px solid #fd9430;
}

.std-self .arrow.down .up-arrow {
    border-bottom: 110px solid #fd9430;
}

.arrow.up .up-arrow {
    border-left: 110px solid transparent;
    border-right: 110px solid transparent;
    border-top: 110px solid transparent;
    position: absolute;
    left: -60px;
    top: -170px;
}

.arrow.down .up-arrow {
    border-left: 110px solid transparent;
    border-right: 110px solid transparent;
    border-top: 110px solid transparent;
    position: absolute;
    left: -60px;
    top: -170px;
}



