.grace-point-table table td p {
	position: relative;
    margin-bottom: 0px;
    display: inline-block;
    vertical-align: middle;
    height: 25px;
}

.grace-point-table table td [type="checkbox"]:not(:checked),
.grace-point-table table td [type="checkbox"]:checked {
	position: absolute;
	left: 0;
	opacity: 0.01;
}


.grace-point-table table td [type="checkbox"]:not(:checked) + label,
.grace-point-table table td [type="checkbox"]:checked + label {
    position: relative;
    font-size: 1.05em;
    cursor: pointer;
    width: 25px;
    display: inline-block;
    height: 25px;
    margin: 0px;
}

.grace-point-table table td [type="checkbox"]:not(:checked) + label:before,
.grace-point-table table td [type="checkbox"]:checked + label:before {
	content: '';
	position: absolute;
	left: 0;
	top: 0;
	width: 1.4em;
	height: 1.4em;
	border: 1px solid #aaa;
	border-radius: .2em;
	box-shadow: inset 0 1px 3px rgba(0,0,0, .1), 0 0 0 rgba(203, 34, 237, .2);
	transition: all .275s;
}


/* .grace-point-table table td .green [type="checkbox"]:not(:checked) + label:before, */
.grace-point-table table td .green [type="checkbox"]:checked + label:before {
	background: #2b910f;
}

/* .grace-point-table table td .red [type="checkbox"]:not(:checked) + label:before, */
.grace-point-table table td .red [type="checkbox"]:checked + label:before {
	background: #f02116;
}


.grace-point-table table td [type="checkbox"]:not(:checked) + label:after,
.grace-point-table table td [type="checkbox"]:checked + label:after {
	content: '✓';
    position: absolute;
    top: 13px;
    left: 5px;
    font-size: 20px;
    color: #fff;
    line-height: 0;
    transition: all .2s;
}


.grace-point-table table td [type="checkbox"]:not(:checked) + label:after {
	opacity: 0;
	transform: scale(0) rotate(45deg);
}


.grace-point-table table td [type="checkbox"]:checked + label:after {
	opacity: 1;
	transform: scale(1) rotate(0);
}

.grace-point-table .table-striped > tbody > tr:nth-of-type(odd),
.grace-point-table .table-striped > tbody > tr:nth-of-type(even),
.grace-point-table .table-hover > tbody > tr:hover {
