/* Base for label styling */
.portal-check [type="checkbox"]:not(:checked),
.portal-check [type="checkbox"]:checked {
  position: absolute;
  left: -9999px;
}
.portal-check [type="checkbox"]:not(:checked) + label,
.portal-check [type="checkbox"]:checked + label {
    position: relative;
    padding-left: 0px;
    cursor: pointer;
    margin: 0px;
    display: inline-block;
    width: 20px;
    height: 20px;
}

/* checkbox aspect */
.portal-check [type="checkbox"]:not(:checked) + label:before,
.portal-check [type="checkbox"]:checked + label:before {
	content: '';
    position: absolute;
    left: 0px;
    top: 0px;
    width: 20px;
    height: 20px;
    border: 2px solid #ccc;
    background: #fff;
    border-radius: 4px;
    box-shadow: inset 0 1px 3px rgba(0,0,0,.1);
}
/* checked mark aspect */
.portal-check [type="checkbox"]:not(:checked) + label:after,
.portal-check [type="checkbox"]:checked + label:after {
	content: '\2713\0020';
    position: absolute;
    top: -1px;
    left: 0px;
    font-size: 16px;
    line-height: normal;
    color: #09ad7e;
    transition: all .2s ease-in-out;
    width: 20px;
    height: 20px;
    font-weight: 600;
}
/* checked mark aspect changes */
.portal-check [type="checkbox"]:not(:checked) + label:after {
  opacity: 0;
  transform: scale(0);
}
.portal-check [type="checkbox"]:checked + label:after {
  opacity: 1;
  transform: scale(1);
}

.portal-check {
	text-align: center;
	margin: 0px;
	height: 20px;
}

