.form-new-radio [type="radio"]:checked,
.form-new-radio [type="radio"]:not(:checked) {
    position: absolute;
    left: -9999px;
}
.form-new-radio [type="radio"]:checked + label,
.form-new-radio [type="radio"]:not(:checked) + label
{
	position: relative;
    padding-left: 23px;
    cursor: pointer;
    line-height: 20px;
    display: inline-block;
    color: #44426a;
}
.form-new-radio [type="radio"]:checked + label:before,
.form-new-radio [type="radio"]:not(:checked) + label:before {
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    width: 18px;
    height: 18px;
    border: 1px solid #0841d073;
    border-radius: 100%;
    background: #fff;
}
.form-new-radio [type="radio"]:checked + label:after,
.form-new-radio [type="radio"]:not(:checked) + label:after {
    content: '';
    width: 12px;
    height: 12px;
    background: #0841d0;
    position: absolute;
	top: 3px;
    left: 3px;
    border-radius: 100%;
    -webkit-transition: all 0.2s ease;
    transition: all 0.2s ease;
}
.form-new-radio [type="radio"]:not(:checked) + label:after {
    opacity: 0;
    -webkit-transform: scale(0);
    transform: scale(0);
}
.form-new-radio [type="radio"]:checked + label:after {
    opacity: 1;
    -webkit-transform: scale(1);
    transform: scale(1);
}

