	height: initial;
	width: initial;
	margin-bottom: 0;
	display: none;
	cursor: pointer;
}

.self-knowledge-checklist label {
	position: relative;
    cursor: pointer;
    font-size: 22px;
    color: #44426a;
    padding-left: 34px;
}

.self-knowledge-checklist label:before {
	content: '';
    -webkit-appearance: none;
    background-color: transparent;
    border: 2px solid #001c4e;
    padding: 8px;
    display: inline-block;
    vertical-align: middle;
    cursor: pointer;
    position: absolute;
    left: 0px;
    top: 5px;
    box-shadow: 1px 2px 1px #001c4e;
}

.self-knowledge-checklist input:checked + label:after {
	content: '';
    display: block;
    position: absolute;
    top: 8px;
    left: 8px;
    width: 6px;
    height: 12px;
    border: solid #001c4e;
    border-width: 0 2px 2px 0;
    transform: rotate(45deg);
}
