.rating li span {
    font-family: BlinkMacSystemFont,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    display: none;
    position: absolute;
    top: -33px;
    left: 50%;
    margin-left: 0 !important;
    background-color: #FFF;
    color: rgba(0,0,0,0.8);
    width: auto !important;
    min-width: 45px;
    border: 1px solid #BFBFBF;
    border-radius: 0;
    padding: 3px 7px;
    font-size: 13px;
    text-align: center;
    white-space: nowrap;
    transform: translateX(-50%);
    -ms-transform: translateX(-50%);
}
.rating li label:hover + span {
	display: block;
}
.rating li span:before, .rating li span:after {
    content: "";
    width: 0;
    position: absolute;
    bottom: -6px;
    left: 50%;
    transform: translateX(-50%);
    -ms-transform: translateX(-50%);
    border-right: 5px solid transparent;
    border-left: 5px solid transparent;
}
.rating li span:before {
    border-top: 6px solid #000;
}
.rating li span:after {
    border-top: 6px solid #FFF;
}
.rating .mood_2 label, .rating .rating_2 label {
    background-position: -30px 0;
}
.rating .mood_3 label, .rating .rating_3 label {
    background-position: -60px 0;
}
.rating .mood_4 label, .rating .rating_4 label {
    background-position: -90px 0;
}
.rating .mood_5 label, .rating .rating_5 label {
    background-position: -120px 0;
}
